const BHITARKANIKA_DATA={id:"bhitarkanika",name:"Bhitarkanika National Park",location:"Kendrapara District, Odisha (Gahirmatha coast)",established:1998,area:"145 km²",altitude:"Sea level (intertidal)",coordinates:{lat:20.762,lng:86.946},bestSeason:"November to February",quickStats:[{label:"Saltwater Crocodiles",value:"1,800+",icon:"🐊"},{label:"Bird Species",value:"240+",icon:"🦤"},{label:"Mangrove Species",value:"60+",icon:"🌿"},{label:"Nesting Olive Ridleys",value:"Lakhs",icon:"🐢"}],ecology:{title:"A Ramsar-Listed Mangrove Wilderness",description:"Bhitarkanika, part of the Bhitarkanika Mangroves, is one of India’s largest and most pristine mangrove ecosystems, formed by the deltaic interlacing of the Brahmani, Baitarani, and Dhamra rivers as they meet the Bay of Bengal. Its creeks, mudflats, and tidal forests shelter the world’s largest known population of estuarine (saltwater) crocodiles and hundreds of resident and migratory bird species.",facts:["Ramsar Wetland of International Importance (2002).","Held the record for the largest saltwater crocodile ever recorded.","Among the most mangrove-diverse stretches of the Odisha coast.","A critical breeding site for the estuarine crocodile and a turtle dispersal corridor."]},mangroves:[{name:"Sundari & Indian Mangrove",status:"Canopy Dominant",desc:"Extensive stands of sundari and avicennia mangroves form dense tidal forests along the creeks.",icon:"🌿"},{name:"Creek & Mudflat Ecosystem",status:"Intertidal",desc:"Network of tidal creeks and mudflats that trap sediment and nourish juvenile marine life.",icon:"🌊"},{name:"Halophytic Specialists",status:"Salt-tolerant",desc:"Salt-tolerant palms, rhizophora, and bruguiera species thrive in brackish water zones.",icon:"🌴"},{name:"Riverine Delta Forests",status:"River-fed",desc:"Deltaic forests fed by the Brahmani and Baitarani rivers with mixed freshwater and saline zones.",icon:"🪷"}],wildlife:[{name:"Saltwater Crocodile",status:"Endangered",desc:"The world’s largest living reptile, with a healthy breeding population here along the tidal creeks.",icon:"🐊"},{name:"King Cobra",status:"Vulnerable",desc:"Asia’s largest venomous snake glides through the mangrove waterways and forests.",icon:"🐍"},{name:"Fishing Cat & Jungle Cat",status:"Vulnerable",desc:"Felids that fish the mangroves are an indicator of the health of these wetland habitats.",icon:"🐈"},{name:"Water Monitor Lizard",status:"Stable",desc:"Large monitor lizards bask along creek banks and mudflats across the park.",icon:"🦎"}],birds:[{name:"Indian Skimmer",status:"Vulnerable",desc:"A striking river tern whose breeding colonies thrive along the sand bars of the delta.",icon:"🐦"},{name:"Black-necked Stork",status:"Near Threatened",desc:"One of the tallest Asian wading birds, seen stalking fish in the shallow creeks.",icon:"🦩"},{name:"Greater Adjutant Stork",status:"Endangered",desc:"The rare scavenging stork finds refuge in the wetland mosaic of Bhitarkanika.",icon:"🦢"},{name:"Migratory Ducks & Waders",status:"Winter Visitor",desc:"Scores of migratory ducks, herons, and sandpipers arrive from northern latitudes each winter.",icon:"🕊️"}],safariZones:[{id:"dangamala",name:"Dangamala Crocodile Rearing Centre",timing:"Safari · 1 hour",desc:"The captive-breeding centre where hatchling estuarine crocodiles are raised before release into the wild.",highlight:"Watch baby crocodiles before boat safari."},{id:"bagagahan",name:"Bagagahan Heronry",timing:"Boat Safari · 1 hour",desc:"A famous nesting heronry where thousands of herons, cormorants, and storks breed from July to October.",highlight:"Best winter heronry in eastern India."},{id:"creek-cruise",name:"Khola Creek Boat Cruise",timing:"Canoe Ride · 2 hours",desc:"Paddle through winding mangrove-lined creeks to spot crocodiles, kingfishers, and marsh crocodiles.",highlight:"Prime crocodile spotting waters."},{id:"ghahirmatha",name:"Gahirmatha Turtle Beach",timing:"Day Trip",desc:"The world’s largest olive ridley turtle rookery on the coast, protected by the Gahirmatha Marine Sanctuary.",highlight:"Mass nesting (arribada) in winter nights."}],mapHotspots:[{id:"khola",name:"Khola Entry Point",desc:"The main gateway to the park where boat safaris begin.",x:300,y:380},{id:"dangamala",name:"Dangamala Centre",desc:"Crocodile rearing centre and heritage mangrove display.",x:500,y:320},{id:"bagagahan",name:"Bagagahan Heronry",desc:"Nesting colony of herons and storks.",x:640,y:200},{id:"ghahirmatha",name:"Gahirmatha Beach",desc:"Olive ridley nesting rookery on the coast.",x:800,y:90}],gallery:[{src:"https://images.unsplash.com/photo-1503785640985-f62e3aeee448?auto=format&fit=crop&w=800&q=80",caption:"Mangrove creeks of Bhitarkanika"},{src:"https://images.unsplash.com/photo-1568515387631-8b650bbcdb90?auto=format&fit=crop&w=800&q=80",caption:"Estuarine crocodile basking"},{src:"https://images.unsplash.com/photo-1505142468610-359e7d316be0?auto=format&fit=crop&w=800&q=80",caption:"Deltaic wetlands at low tide"},{src:"https://images.unsplash.com/photo-1444464666168-49d633b86797?auto=format&fit=crop&w=800&q=80",caption:"Herons and waders of the heronry"}]};